'use strict';
// CC-001 A70: evidence must be generated by THIS managed execution, never inherited from R16.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const sha256 = data => crypto.createHash('sha256').update(data).digest('hex');

function archiveAndRemoveStaleResult(resultPath, evidenceDir) {
  const outcome = { oldResultPresent: false, oldResultSha256: null, archivedPath: null };
  if (!fs.existsSync(resultPath)) return outcome;
  if (!fs.lstatSync(resultPath).isFile()) throw Error('UNSAFE_OLD_TEST_RESULT');
  const previous = fs.readFileSync(resultPath);
  const archivePath = path.join(evidenceDir, 'preexisting-unity-tests.json');
  if (fs.existsSync(archivePath)) throw Error('OLD_RESULT_ARCHIVE_COLLISION');
  fs.writeFileSync(archivePath, previous, { flag: 'wx' });
  fs.unlinkSync(resultPath);
  return { oldResultPresent: true, oldResultSha256: sha256(previous), archivedPath: path.basename(archivePath) };
}
function validateNewResult(resultPath, startedAtMs, finishedAtMs) {
  if (!fs.existsSync(resultPath) || !fs.lstatSync(resultPath).isFile()) throw Error('NEW_TEST_RESULT_MISSING');
  const body = fs.readFileSync(resultPath);
  let parsed;
  try { parsed = JSON.parse(body.toString('utf8')); }
  catch { throw Error('NEW_TEST_RESULT_INVALID_JSON'); }
  if (parsed?.spec !== 'V149 UNITY' || !Number.isSafeInteger(parsed.passed) || parsed.passed <= 0 || parsed.failed !== 0)
    throw Error('MANAGED_TEST_RESULT_BAD_COUNTS');
  if (!Array.isArray(parsed.results) || parsed.results.length !== parsed.passed ||
      !parsed.results.every(x => x && x.pass === true && typeof x.name === 'string' && x.name.length > 0))
    throw Error('MANAGED_TEST_RESULT_BAD_CASES');
  const utc = Date.parse(parsed.testedAt);
  if (!Number.isFinite(utc) || utc < startedAtMs - 300000 || utc > finishedAtMs + 300000)
    throw Error('MANAGED_TEST_RESULT_BAD_TIMESTAMP');
  return { parsed, body, sha256: sha256(body) };
}
module.exports = { archiveAndRemoveStaleResult, validateNewResult };
